import{c as e,Q as a,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"GetSubBlockIdx","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetSubBlockIdx","slug":"getsubblockidx"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetSubBlockIdx.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetSubBlockIdx.md"}'),d={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetSubBlockIdx.md"};function n(i,t,o,r,c,p){return a(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="getsubblockidx" tabindex="-1">GetSubBlockIdx <a class="header-anchor" href="#getsubblockidx" aria-label="Permalink to &quot;GetSubBlockIdx&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>获取当前AIV核的ID。分离架构下，一个AI Core由Cube Core（AIC）和Vector Core（AIV）按照一定比例1：N进行组合，其中N个AIV的子核ID分别为0, 1, ..., N-1。</p><p>Matmul::GetSubBlockIdx()与基础API接口<a href="./../../../基础API/系统变量访问/GetSubBlockIdx(ISASI).html">AscendC::GetSubBlockIdx()</a>的区别在于，Matmul::GetSubBlockIdx()用于获取当前AIV核在当前AI Core分组中的ID，而AscendC::GetSubBlockIdx()获取的是AIV核在所有AI Core分组中的逻辑ID。例如，有10组AI Core，AIC与AIV的比例为1:2，共20个AIV核。调用Matmul::GetSubBlockIdx()时，20个AIV的获取结果依次为0, 1, 0, 1, 0, 1, ..., 0, 1。调用AscendC::GetSubBlockIdx()时，20个AIV的获取结果依次为0, 1, 2, 3, 4, 5, ..., 18, 19。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__  inline uint8_t GetSubBlockIdx()</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p>无</p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>当前AIV核的ID。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>该接口仅支持在分离架构下使用，否则返回随机值。</li><li>在分离架构中，AIV核的ID会在<a href="./REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ()</a>接口内部自动初始化和赋值。因此，需要在调用REGIST_MATMUL_OBJ()接口之后，再调用本接口，以获取正确的ID。</li><li>若在算子程序中调用<a href="./SetSubBlockIdx.html">SetSubBlockIdx()</a>后， GetSubBlockIdx()接口将返回由SetSubBlockIdx接口设置的ID值。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_NORM&gt; mm;</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>mm.GetSubBlockIdx(); // 获取子核ID</span></span></code></pre></div>`,16)])])}const I=e(d,[["render",n]]);export{h as __pageData,I as default};
